package com.shatteredpixel.shatteredpixeldungeon.apd.mechanics;

import com.shatteredpixel.shatteredpixeldungeon.Dungeon;
import com.shatteredpixel.shatteredpixeldungeon.actors.buffs.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero;
import com.shatteredpixel.shatteredpixeldungeon.items.Item;

/** Additional reviewed status rules, with no random rolls or effect-handler calls. */
public final class BuffExplanation {
    private BuffExplanation(){}
    private static String n(float x){return ObfuscationExplanation.number(x);}
    public static String details(Buff buff){
        if(buff.target==com.shatteredpixel.shatteredpixeldungeon.Dungeon.hero&&Dungeon.hero!=null){
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWeapon.HolyWepBuff)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWeapon.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWard.HolyArmBuff)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWard.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.AuraOfProtection.AuraBuff)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.AuraOfProtection.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.ShieldOfLight.ShieldOfLightTracker)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.ShieldOfLight.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.DivineSense.DivineSenseTracker)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.DivineSense.INSTANCE,Dungeon.hero);
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.GuidingLight.Illuminated&&Dungeon.hero!=null)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.GuidingLight.INSTANCE,Dungeon.hero);
        if(buff instanceof MagicalSight)return "_Magical sight range_\nAdds terrain sensing through walls in a rounded radius of "+MagicalSight.DISTANCE+" tiles around the hero, clipped by floor boundaries and terrain the game can reveal. It overlays normal sight instead of limiting longer normal vision. When combined with Mind Vision's nearby terrain sense, the larger sensing radius is used; the radii are not added. Seeing a disguised secret-door or hidden-trap tile does not automatically discover that secret. The effect removes Blindness when attached and grants Blindness immunity while present.";
        if(buff instanceof MindVision)return "_Mind Vision's two kinds of sight_\nThe local terrain-sensing radius from this effect is "+((MindVision)buff).distance+" tiles, overlaid on normal sight and combined with other sensing radii by taking the larger value. Separately, it senses eligible creatures across the floor and reveals the nearby area around them. This is not full-floor terrain mapping. Hidden neutral stealthy mimics and object-like entities are excluded from that creature-sensing pass. Seeing a creature this way does not create a clear physical projectile path through walls.";
        if(buff instanceof Invisibility)return "_Invisibility and enemy awareness_\nInvisibility prevents ordinary visual tracking while active; it is not an added stealth percentage or a multiplier on the Obfuscation score. A hunting enemy can still investigate the last position it knew, and environmental damage, area effects or special sensing can still matter. Normal attacks and many magical actions dispel invisibility under their own rules. Several sources can keep invisibility active, so ending one timed source need not remove another.";
        if(buff instanceof Invulnerability)return "_Temporary damage protection_\nWhile active, this effect blocks ordinary damage processing before resistance, shielding and HP loss. That does not make every harmful status impossible to apply or guarantee survival against every special direct-death rule. It has a scheduled duration rather than a pool of shield points; taking a protected hit does not spend a damage reserve.";
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.plants.Sungrass.Health){
            com.shatteredpixel.shatteredpixeldungeon.plants.Sungrass.Health healing=(com.shatteredpixel.shatteredpixeldungeon.plants.Sungrass.Health)buff;
            String result="_Location-bound herbal healing_\nRemaining unmodified pool: "+healing.remainingPool()+" HP. Each normal one-turn update adds (40 + maximum HP) / 150 toward a healing request. Only when that progress is strictly greater than 1 does it request the whole-number part and retain the fraction. The request spends that many pool points before normal healing adjustments and missing-HP limits. The final request is not separately capped to the remaining pool. Repeated boosts add to the pool and anchor it at the recipient's current tile. Moving ends it, but the update detecting movement can still finish its heal step.";
            if(buff.target==Dungeon.hero&&Dungeon.hero!=null)result+="\nYour current progress: "+n(healing.healingProgress())+" HP toward a request; next unmodified request: "+healing.nextUnmodifiedRequest()+" HP. This is not a promise of that much actual HP restored under every healing rule.";
            return result;
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLivingEarth.RockArmor){
            com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLivingEarth.RockArmor armor=(com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLivingEarth.RockArmor)buff;
            return "_Rock Armor reserve_\nCurrent reserve: "+armor.remainingReserve()+" damage-blocking points. At its qualifying incoming-attack step, it blocks min(reserve, ceil(damage entering this step / 2)) and spends that reserve. Small odd hits round their half-block upward; this is not exactly 50% less final HP lost in every case. Guardian threshold: "+armor.guardianThreshold()+" reserve points, from 8 + 4 × stored wand level; reserve cap: "+(2*armor.guardianThreshold())+" points. Reaching the threshold does not instantly summon a guardian: the wand checks creation on a subsequent qualifying zap.";
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.plants.Earthroot.Armor){
            com.shatteredpixel.shatteredpixeldungeon.plants.Earthroot.Armor armor=(com.shatteredpixel.shatteredpixeldungeon.plants.Earthroot.Armor)buff;
            return "_Earthroot block and reserve_\nCurrent per-hit limit: "+armor.perHitLimit()+" damage points, from floor((scaling floor depth + 5) / 2). Remaining reserve: "+armor.remainingReserve()+" points. Each qualifying hit while you remain on the protected tile blocks min(incoming damage, per-hit limit). The reserve is spent by blocked amounts, but the last protected hit can use the full per-hit limit even when less reserve remains; it then ends. Moving prevents further absorption. This is added blocking at its own step, not a permanent armor upgrade or an HP shield.";
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLightning.LightningCharge)return "_Lightning Charge_\nWhile active, Lightning wand zaps exclude charged characters from their damage targets. The caster's Lightning wand propagation radius gains one tile: normally one tile, or two through a wet target, before adding this charge bonus. This is not added melee reach or protection against every other electricity source. Reapplication keeps the longer scheduled duration rather than adding both durations.";
        if(buff instanceof Paralysis){
            String result="_Breaking paralysis_\nAt the damage check, the qualifying incoming damage is added to the damage counted toward resisting paralysis. This check occurs before shield points absorb the hit and before HP is subtracted, so shielding does not necessarily prevent an escape check. Roll an integer from zero through that accumulated amount and a separate integer from zero through current HP; both rolls favor the middle of their ranges. Paralysis breaks if the first roll is at least the second. This is not a fixed escape percentage or a guarantee that each hit breaks it.\nFor each bound N, the roll is truncate((first uniform fraction + second uniform fraction) × (N + 1) / 2), with independent fractions from 0 up to but excluding 1. While no Paralysis remains, the accumulated amount loses ceil(amount / 10) on each resistance update until zero. Other incapacitating effects can still prevent action after this one ends.";
            if(buff.target==Dungeon.hero&&Dungeon.hero!=null){Paralysis.ParalysisResist resistance=Dungeon.hero.buff(Paralysis.ParalysisResist.class);result+="\nYour current counted damage: "+(resistance==null?0:resistance.accumulatedDamage())+" damage points. This is the escape calculation's accumulated amount, not HP already lost or damage still to come.";}
            return result;
        }
        if(buff instanceof Drowsy)return "_Drowsiness becoming sleep_\nWhen its scheduled duration finishes, Drowsy attempts Magical Sleep; immunity to Sleep prevents that result. The hero's incoming-damage handling can remove Drowsy before final HP loss is resolved. Being at full health prevents the ally/hero restorative sleep from persisting, rather than providing a random resistance percentage. Drowsy itself does not heal or deal damage.";
        if(buff instanceof MagicalSleep)return "_Magical sleep and recovery_\nAllied sleepers request one unmodified HP of healing on each one-turn sleep update, limited by missing HP and the normal healing rules. The run’s healing modifiers and fractional healing adjustments can change the actual amount gained. Allies wake when their HP reaches maximum; a hero with restorative healing disabled does not remain locked asleep. Hostile sleepers do not receive this restorative healing. Damage and special wake-up rules can end sleep sooner. There is no ordinary fixed countdown for this effect, and other paralysis-like effects can still prevent action after it ends.";
        if(buff instanceof FireImbue){FireImbue fire=(FireImbue)buff;return "_Fire imbue_\nEach qualifying landed attack makes a separate 1-in-2 (50%) check to attempt Burning. It is not guaranteed ignition or a fixed extra damage amount; Burning immunity and the target's other rules still matter. The wearer is immune to Burning, and attaching this effect removes existing Burning. Remaining imbue duration: "+n(fire.remainingDuration())+" turns; normal updates subtract one turn, set replaces the duration and extensions add to it. This is not a promise of immunity to every fire-themed special effect.";}
        if(buff instanceof FrostImbue)return "_Frost imbue_\nEach qualifying landed attack offers three turns of Chill before the target's duration resistance. Repeated applications add that scheduled duration rather than adding direct damage. Chill's own action-rate formula limits its slowdown to half normal; Slow takes priority over Chill instead of multiplying both. The wearer is immune to Chill and Frost, and attaching this effect removes those existing statuses. It does not prevent every damage source with an icy appearance.";
        if(buff instanceof Adrenaline)return "_Movement and attack timing_\nAdrenaline multiplies movement speed by 2, so an otherwise unchanged step costs half its usual game time. It combines with separate movement modifiers. Normal monster attack timing also divides attack delay by 1.5, giving two thirds of the usual attack time. The hero does not gain that monster-only attack-speed bonus; other creatures' special attack rules can differ. This does not multiply damage.";
        if(buff instanceof Cripple)return "_Movement penalty_\nCripple divides movement speed by 2, so an otherwise unchanged step costs twice its usual game time. It combines multiplicatively with other movement-rate effects, not by adding their percentages. It does not by itself double attack time or reduce damage.";
        if(buff instanceof Stamina)return "_Movement bonus_\nStamina multiplies movement speed by 1.5, so an otherwise unchanged step costs two thirds of its usual game time. It does not add 50 percentage points to dodge chance, multiply damage or speed up every action. Other movement modifiers can still combine with it.";
        if(buff instanceof Fury)return "_Fury damage and ending condition_\nFury multiplies qualifying physical attack damage by 1.5 at its attack-damage step. Armor, later attack effects and protection can change final HP loss. On its next normal update, Fury ends if current HP is strictly above "+n(100*Fury.LEVEL)+"% of maximum HP. At exactly that percentage it remains active. This is a health condition, not an ordinary fixed-duration countdown.";
        if(buff instanceof Healing){Healing healing=(Healing)buff;return "_Healing requests and pool_\nThe next unmodified healing request is "+healing.nextRequestedHealing()+" HP. Remaining unmodified pool: "+healing.remainingHealingPool()+" HP. While its pool is positive, each tick requests clamp(round(remaining pool × rate) + flat amount, 1, remaining pool). Current rate: "+n(100*healing.healingRate())+"% of the remaining pool; flat amount: "+healing.flatHealing()+" HP, with the applicable Blood Vial per-tick limit afterward. "+(healing.healingPerTickLimit()==Integer.MAX_VALUE?"No Blood Vial limit applies.":"Current Blood Vial limit: "+healing.healingPerTickLimit()+" HP per tick.")+" Normal healing rules and missing HP determine actual HP gained. The pool is spent using the unmodified request, not a promise of that many HP restored under every rule. Reapplications keep the larger remaining pool and the stronger rate/flat components rather than simply adding every heal.";}
        if(buff instanceof Burning){Burning burning=(Burning)buff;return "_Burning damage and timing_\nRemaining duration: "+n(burning.apdRemaining())+" turns. The ordinary unmodified damage roll is 1–"+burning.apdRandomMaximum()+" damage points, biased toward the middle, before source-specific and target modifiers. The maximum uses 3 + floor(scaling depth / 4); it is not a fixed percentage of HP. Water can remove Burning, but removal does not undo a tick already resolved. Burning immunity prevents the damage, and an active Brimstone glyph can separately turn attempted ignition into Barrier shielding. Fire can also affect exposed burnable items; protected containers and other item rules matter.";}
        if(buff instanceof Corrosion){Corrosion corrosion=(Corrosion)buff;return "_Corrosion strength_\nNext unmodified tick input: "+corrosion.apdNextRaw()+" damage points. Remaining duration: "+n(corrosion.apdRemaining())+" turns. After each tick, strength rises by 1 while below floor(scaling depth / 2) + 2; afterward it rises by 0.5. The tick amount is truncated to an integer, so a half-point increase need not change every displayed tick. Source modifiers, immunity and defenses determine final HP loss. New applications keep the stronger strength and longer remaining duration; the latest source policy still applies.";}
        if(buff instanceof Ooze){Ooze ooze=(Ooze)buff;return "_Ooze damage and timing_\nThe next ordinary unmodified input under its duration/floor rule is "+ooze.apdNextRaw()+" damage points before washing-off and source/target modifiers. Remaining duration: "+n(ooze.apdRemaining())+" turns. Above scaling depth5, raw damage is 1 + floor(depth / 5) per tick; at depth5 it is one per tick; below that it is one only when the integer remaining duration is even. Water washing and a newly applied effect's first-tick ordering matter; zero on an alternating tick does not mean the effect is permanently harmless.";}
        if(buff instanceof AdrenalineSurge){AdrenalineSurge surge=(AdrenalineSurge)buff;return "_Temporary strength_\nCurrent added strength: "+surge.boost()+" points. Its next scheduled weakening is in "+n(Math.max(0,surge.visualcooldown()))+" game-time units. Each weakening removes one strength point, then schedules the next after "+n(surge.weakeningInterval())+" turns while any boost remains. These points affect strength-based mechanics; they are not that many percent more damage or health.";}
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure.EndureTracker){
            com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure.EndureTracker endure=(com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure.EndureTracker)buff;
            String state=endure.enduring?"Currently enduring: stored retaliation amount "+endure.damageBonus+" points before the conversion multipliers and per-hit division.":"Retaliation ready: +"+endure.damageBonus+" damage points on each of "+endure.hitsLeft+" remaining qualifying hits reaching the attack-damage step.";
            return "_Endure state_\n"+state+(buff.target instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero?AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure(),(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero)buff.target):"");
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower.naturesPowerTracker){
            com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower.naturesPowerTracker power=(com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower.naturesPowerTracker)buff;
            return "_Nature's Power extensions_\nRemaining qualifying extension opportunities: "+power.extensionsLeft+". Only a positive extension spends an opportunity."+(buff.target instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero?AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower(),(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero)buff.target):"");
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm.AscendBuff){
            com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm.AscendBuff form=(com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm.AscendBuff)buff;
            return "_Current ascended resources_\nForm shield: "+form.shielding()+" points. Remaining form updates: "+form.left+". Counted spell casts: "+form.spellCasts+". Flash uses counted: "+form.flashCasts+". These are separate shield, time and use resources; inspecting does not change them."+(buff.target instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero?AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm(),(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero)buff.target):"");
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.PowerOfMany.PowerBuff)return "_Powered ally_\nThe ally retains its own equipment, health and targeting rules. Power modifies attack damage and incoming damage at separate steps; the icon's duration is not a shield-point amount."+AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.PowerOfMany(),Dungeon.hero);
        if(buff instanceof PhysicalEmpower){PhysicalEmpower empower=(PhysicalEmpower)buff;return "_Added physical damage_\nCurrent benefit: +"+empower.dmgBoost+" damage points per qualifying hero physical damage roll; "+empower.left+" rolls remain. The hero's damage-roll handler adds these points and spends one use, before later modifiers and defenses. This is not a percentage or a permanent weapon upgrade. A new offer replaces it only if offered points × offered rolls exceeds current points × remaining rolls. The two amounts are not added together.";}
        if(buff instanceof WandEmpower){WandEmpower empower=(WandEmpower)buff;return "_Wand damage contribution_\nAdds "+empower.dmgBoost+" damage points to each of the next "+empower.left+" qualifying direct-wand damage rolls. This is added damage, not an upgrade level or a percentage. The counter is consumed by those rolls, so a multi-target/multi-roll action can differ from one simple zap; indirect damage sources do not all use this path. A new application replaces the bonus amount and keeps the larger remaining-roll count.";}
        if(buff instanceof Degrade){StringBuilder result=new StringBuilder("_Degradation curve_\nAt this stage, levels ≤ 0 are unchanged. Positive levels use round(sqrt(2 × (level − 1)) + 1). This is a rounded square-root curve, not exponential decay. It changes effective upgrade benefits rather than permanently removing upgrades. Strength requirements, normal wand-charge capacity, ordinary thrown durability and artifacts keep their separate rules. Other temporary bonuses can apply at other stages.\n");
            if(buff.target==Dungeon.hero&&buff.target instanceof Hero){Hero hero=(Hero)buff.target;for(Item item:new Item[]{hero.belongings.weapon(),hero.belongings.armor(),hero.belongings.ring(),hero.belongings.misc()})if(item!=null&&!(item instanceof com.shatteredpixel.shatteredpixeldungeon.items.artifacts.Artifact)&&item.levelKnown)result.append("\n").append(item.name()).append(": known level ").append(item.level()).append("; degradation-only result ").append(Degrade.reduceLevel(item.level())).append(" before other bonuses.");}
            return result.toString();}
        if(buff instanceof Doom)return "_Doom's damage stage_\nEligible incoming damage is multiplied by 1.67 at Doom's stage, before later source-resistance, rounding and protection steps. It does not add a flat 67 damage points, bypass immunity, or guarantee 67% more final HP loss. Immunity to Doom prevents this modifier. The effect has no ordinary duration countdown.";
        if(buff instanceof Corruption)return "_Corruption's gradual harm_\nEach normal tick adds target maximum HP / 100 to a damage accumulator. Its whole damage points are sent to the normal damage handler and its fractional remainder is retained. This is base 1% maximum HP per tick, not 1% of the HP currently left or a guaranteed fixed lifetime through every defense. Corruption also changes allegiance; the original attack and target rules still apply.";
        if(buff instanceof Berserk){Berserk rage=(Berserk)buff;return "_Rage and damage_\nCurrent rage: "+n(100*rage.rageFraction())+"%. Its damage factor is min(1.5, 1 + rage / 2), where 100% rage means rage = 1; current factor: "+n(rage.damageFactor(1))+" times normal at this step. Rage above 100% does not raise that factor past 1.5. The berserk shield formula starts from 8 + 2 × effective armor level (zero armor contribution when no armor is available) and multiplies by 1 + 2 × (missing-HP fraction)³, then by rage when rage exceeds1, with integer rounding. Active berserk shield loss is based on total current shielding, not a fixed amount: ceil(total shield × 0.025), modified by Hold Fast and fractional rounding. Shield/HP, armor, recovery and other effects still follow their own rules.";}
        if(buff instanceof ChampionEnemy){
            ChampionEnemy champion=(ChampionEnemy)buff;
            String result="_Champion contributions_\nThis champion effect multiplies qualifying attack damage by "+n(champion.meleeDamageFactor())
                +", accuracy and evasion contest scores by "+n(champion.evasionAndAccuracyFactor())
                +", and damage entering its incoming-damage step by "+n(champion.damageTakenFactor())
                +". Incoming damage at that step rounds upward to a whole damage point. These are separate factors, not added damage points or hit/dodge percentages. Other defenses, immunity and shielding can still change the final health lost.";
            if(buff instanceof ChampionEnemy.Growing)result+="\nEach scheduled growth tick adds 0.01 to the damage/accuracy/evasion factor and schedules the next tick four turns later. Incoming damage uses the reciprocal, 1 / that factor. Growth adds to the factor; it does not multiply the previous factor by 1.01. This effect has no fixed growth cap. Displayed whole percentages can hide a fractional difference; the factors above use the current saved state.";
            if(buff instanceof ChampionEnemy.Projecting)result+="\nExtra-reach attacks require a legal path of at most four tiles through non-solid terrain, without other creatures blocking the path. The extra reach does not mean an attack can pass through a wall.";
            if(buff instanceof ChampionEnemy.Giant)result+="\nExtra-reach attacks require a legal path of at most two tiles through non-solid terrain, without other creatures blocking the path. Large-creature movement restrictions still apply.";
            if(buff instanceof ChampionEnemy.AntiMagic)result+="\nImmunity applies to the game's supported Antimagic spell and effect types. It is not immunity to every possible magical-looking attack or all damage sources.";
            return result;
        }
        return "";
    }
}
